// Native rendered sheets only. No rotating, stretching or re-posing pixels here.
export const SLOTS={hat:{label:'หมวก',choices:[['none','ไม่ใส่'],['hood','ฮู้ดผ้าครีม'],['helm','หมวกเหล็ก']]},shirt:{label:'เสื้อ',choices:[['none','ไม่ใส่'],['tunic','เสื้อคลุมป่า'],['plate','เกราะเหล็ก'],['plum','เสื้อคลุมพลัม']]},pants:{label:'กางเกง',choices:[['none','ไม่ใส่'],['trousers','กางเกงสีถ่าน'],['leather','กางเกงหนัง']]},weapon:{label:'อาวุธ',choices:[['none','ไม่ใส่'],['sword','ดาบเหล็ก'],['sabre','ดาบทองเหลือง']]},wrist:{label:'ข้อมือ',choices:[['none','ไม่ใส่'],['bracer','ข้อมือทองแดง'],['cuff','ผ้าพันข้อมือ']]},boots:{label:'รองเท้า',choices:[['none','ไม่ใส่'],['boots','รองเท้าหนัง'],['greaves','เกราะขา']]}};
export const DEFAULT_OUTFIT={hat:'none',shirt:'tunic',pants:'trousers',weapon:'sword',wrist:'bracer',boots:'boots'};
export const ACTIONS={idle:{label:'ยืน'},walk:{label:'เดิน'},attack:{label:'ตีธรรมดา',damage:24},slam:{label:'ฟาด',damage:58},leap:{label:'กระโดดพุ่งโจมตี',damage:76}};
const ROOT=new URL('../../sprites3d/adventurer/',import.meta.url),files=new Map();let data;
const slotMap={shirt:'chest',pants:'legs'};
async function file(path){if(files.has(path))return;const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('โหลดภาพ 3D ไม่สำเร็จ: '+path));image.src=new URL(path,ROOT);});const c=document.createElement('canvas');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);files.set(path,{image,rgba:c.getContext('2d').getImageData(0,0,c.width,c.height).data,width:c.width});}
export async function loadArt(){if(data)return data;const response=await fetch(new URL('sprites3d.json',ROOT));if(!response.ok)throw Error('ภาพ Blender ยังเรนเดอร์ไม่เสร็จ');data=await response.json();const paths=[];for(const [name,spec]of Object.entries(data.animations)){const a=ACTIONS[name];a.frames=spec.frames;a.frameMs=spec.frameMs;a.duration=spec.frameMs.reduce((n,v)=>n+v,0);a.impact=spec.impact===null?null:spec.frameMs.slice(0,spec.impact).reduce((n,v)=>n+v,0)/a.duration;paths.push(data.body[name].file,data.body[name].depth,data.head[name],spec.fx.file);}for(const items of Object.values(data.layers))for(const item of Object.values(items))paths.push(...Object.values(item.files),...Object.values(item.depth));await Promise.all([...new Set(paths)].map(file));return data;}
export function frameIndex(mode,t){const a=ACTIONS[mode];let elapsed=0;for(let i=0;i<a.frames;i++){elapsed+=a.frameMs[i];if(t*a.duration<elapsed)return i;}return a.frames-1;}
export function progressForFrame(mode,index){const a=ACTIONS[mode];return a.frameMs.slice(0,index).reduce((n,v)=>n+v,0)/a.duration;}
const make=()=>{const c=document.createElement('canvas');c.width=c.height=128;c.getContext('2d').imageSmoothingEnabled=false;return c;};
export class PaperDoll{
 constructor(){this.layers=Object.fromEntries(['body',...Object.keys(SLOTS)].map(k=>[k,make()]));this.frame=make();this.fx=make();this.cacheKey='';}
 draw(outfit,mode,t){const index=frameIndex(mode,t),key=mode+index+JSON.stringify(outfit);if(key!==this.cacheKey){const entries=[['body',data.body[mode].file,data.body[mode].depth]];for(const [slot,item]of Object.entries(outfit))if(item!=='none'){const entry=data.layers[slotMap[slot]||slot][item];entries.push([slot,entry.files[mode],entry.depth[mode]]);}for(const c of Object.values(this.layers))c.getContext('2d').clearRect(0,0,128,128);const pixels=new Uint8ClampedArray(96*96*4),depth=new Uint8Array(96*96),front=new Uint8Array(96*96);depth.fill(255);
   for(const [slot,path,zpath]of entries){const img=files.get(path),z=files.get(zpath);this.layers[slot].getContext('2d').drawImage(img.image,index*96,0,96,96,16,30,96,96);if(slot==='hat')continue;for(let y=0;y<96;y++)for(let x=0;x<96;x++){const src=(y*img.width+index*96+x)*4,dst=(y*96+x)*4;if(img.rgba[src+3]&&z.rgba[src]<depth[y*96+x]){pixels.set(img.rgba.subarray(src,src+4),dst);depth[y*96+x]=z.rgba[src];front[y*96+x]=z.rgba[src+1]>127;}}}
   const overlays=[data.head[mode]];if(outfit.hat!=='none')overlays.push(data.layers.hat[outfit.hat].files[mode]);for(const path of overlays){const img=files.get(path);for(let y=0;y<96;y++)for(let x=0;x<96;x++){const src=(y*img.width+index*96+x)*4;if(img.rgba[src+3]&&!front[y*96+x])pixels.set(img.rgba.subarray(src,src+4),(y*96+x)*4);}}
   // Outlines are baked into every layer offline (pack_sprites3d.py: ring + inner lines with depth), so the
   // depth test above already draws them for any outfit; adding another ring here would double the outline.
   const temp=document.createElement('canvas');temp.width=temp.height=96;temp.getContext('2d').putImageData(new ImageData(pixels,96,96),0,0);const c=this.frame.getContext('2d');c.clearRect(0,0,128,128);c.drawImage(temp,16,30);this.cacheKey=key;
 }const fc=this.fx.getContext('2d');fc.clearRect(0,0,128,128);fc.drawImage(files.get(data.animations[mode].fx.file).image,index*96,0,96,96,16,30,96,96);const a=data.anchors[mode][index];return{image:this.frame,fx:this.fx,layers:this.layers,pose:{frame:index,anchors:a,rootX:mode==='leap'?Math.round(20*Math.sin(Math.PI*t)):0,rootY:0,weaponHand:'right',grip:a.rightHand}};}
}
